out=[];seen={}
for c,f,k,n in D:
    for s,t in(("kort",k),("naturlig",n)):
        out.append(dict(code=c,flate=f,stil=s,tekst=t))
        key=" ".join(t.split()[:3])
        if s=="naturlig" or len(t.split())>=3:
            seen.setdefault(key,[]).append(c+s)
        assert s=="naturlig" or len(t.split())<=4,(c,t)
for k,v in seen.items():
    if len(v)>1: print("DUP",k,v)
json.dump(out,open(sys.argv[1],"w"),ensure_ascii=False,indent=0)
print(len(out))
